SRC_FILES = {'src/__init__.py': '', 'src/data/__init__.py': '', 'src/data/load_data.py': '"""Load dan seragamkan data Datavidia 10: ISPU 2010–2025 (format kolom dan tanggal berbeda tiap tahun), cuaca, libur."""\nfrom __future__ import annotations\n\nimport glob\nimport os\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nCATEGORIES = ["BAIK", "SEDANG", "TIDAK SEHAT", "SANGAT TIDAK SEHAT", "BERBAHAYA"]\nMODEL_CLASSES = ["BAIK", "SEDANG", "TIDAK SEHAT"]          # sangat tidak sehat & berbahaya digabung ke tidak sehat\nSTATIONS = ["DKI1", "DKI2", "DKI3", "DKI4", "DKI5"]\nRENAME = {"pm_sepuluh": "pm10", "pm_10": "pm10", "pm_duakomalima": "pm25", "sulfur_dioksida": "so2",\n          "karbon_monoksida": "co", "ozon": "o3", "nitrogen_dioksida": "no2", "parameter_pencemar_kritis": "critical",\n          "categori": "kategori", "lokasi_spku": "stasiun"}\n\n\ndef find_data_dir(local: str | Path = "../data/raw") -> Path:\n    """Folder yang berisi subfolder ISPU/ dan sample_submission.csv (di /kaggle/input, ikuti symlink)."""\n    for root, dirs, files in os.walk("/kaggle/input", followlinks=True):\n        if "ISPU" in dirs and "sample_submission.csv" in files:\n            return Path(root)\n    return Path(local)\n\n\ndef _parse_dates(s: pd.Series) -> pd.Series:\n    """Tanggal ISO, dd/mm/yyyy (2018), atau nomor seri Excel (beberapa baris 2022)."""\n    s = s.astype(str).str.strip()\n    slash = s.str.contains("/")\n    iso = pd.to_datetime(s.where(~slash), errors="coerce", format="mixed")\n    dmy = pd.to_datetime(s.where(slash), errors="coerce", dayfirst=True, format="mixed")\n    num = pd.to_numeric(s, errors="coerce")\n    xl = pd.to_datetime("1899-12-30") + pd.to_timedelta(num.fillna(0).astype(int), unit="D")\n    return iso.fillna(dmy).fillna(xl.where(num.notna() & (num > 30000))).dt.normalize()\n\n\ndef load_ispu(data_dir: str | Path) -> pd.DataFrame:\n    frames = []\n    for f in sorted(glob.glob(str(Path(data_dir) / "ISPU" / "*.csv"))):\n        x = pd.read_csv(f).rename(columns=RENAME)\n        if "bulan" in x.columns and x.tanggal.astype(str).str.len().max() <= 2:     # 2023–2025: tanggal = hari\n            x["tanggal"] = pd.to_datetime(x.periode_data.astype(str).str[:4] + "-" + x.bulan.astype(str) + "-"\n                                          + x.tanggal.astype(str), errors="coerce")\n        else:\n            x["tanggal"] = _parse_dates(x.tanggal)\n        frames.append(x)\n    d = pd.concat(frames, ignore_index=True)\n    d["station"] = d.stasiun.astype(str).str.extract(r"(DKI\\s?\\d)")[0].str.replace(" ", "")\n    for c in ["pm10", "pm25", "so2", "co", "o3", "no2", "max"]:\n        d[c] = pd.to_numeric(d[c], errors="coerce")\n    d["kategori"] = d.kategori.astype(str).str.upper().str.strip()\n    d["critical"] = d.critical.astype(str).str.upper().str.replace(",", ".").str.replace(r"PM2\\.?5", "PM25", regex=True)\n    raw_rows = len(d)\n    d = d[d.kategori.isin(CATEGORIES) & d.tanggal.notna() & d.station.isin(STATIONS)]\n    d = d.sort_values(["station", "tanggal"]).drop_duplicates(["station", "tanggal"], keep="last")\n    d = d[["tanggal", "station", "pm10", "pm25", "so2", "co", "o3", "no2", "max", "critical", "kategori"]].reset_index(drop=True)\n    d["kelas"] = d.kategori.map({"BAIK": 0, "SEDANG": 1, "TIDAK SEHAT": 2, "SANGAT TIDAK SEHAT": 2, "BERBAHAYA": 2})\n    d.attrs["raw_rows"] = raw_rows\n    return d\n\n\ndef load_holidays(data_dir: str | Path) -> pd.DataFrame:\n    h = pd.read_csv(Path(data_dir) / "libur-nasional" / "dataset-libur-nasional-dan-weekend.csv", parse_dates=["tanggal"])\n    return h[["tanggal", "is_holiday_nasional", "is_weekend"]]\n\n\ndef load_weather(data_dir: str | Path) -> pd.DataFrame:\n    frames = []\n    for f in sorted(glob.glob(str(Path(data_dir) / "cuaca-harian" / "*.csv"))):\n        x = pd.read_csv(f)\n        x = x.rename(columns={"time": "tanggal"})\n        x["tanggal"] = pd.to_datetime(x.tanggal)\n        x["station"] = Path(f).stem.split("-")[2].upper()\n        frames.append(x)\n    w = pd.concat(frames, ignore_index=True)\n    w.columns = [c.split(" (")[0] for c in w.columns]\n    return w.loc[:, ~w.columns.duplicated()]\n', 'src/features/__init__.py': '', 'src/features/build_features.py': '"""Tabel peramalan langsung: dari satu tanggal asal, setiap stasiun diramal untuk 91 hari ke depan.\n\nFitur hanya memakai informasi yang tersedia di tanggal asal (kondisi 30 dan 365 hari terakhir) dan informasi kalender\nyang sudah diketahui sebelumnya (hari dalam tahun, hari dalam minggu, libur nasional).\n"""\nfrom __future__ import annotations\n\nimport numpy as np\nimport pandas as pd\n\nfrom src.data.load_data import STATIONS\n\nCALENDAR = ["stasiun", "doy_sin", "doy_cos", "hari_minggu", "libur"]\nSTATE = ["r30_max", "r30_tidak_sehat", "r30_baik", "r365_max", "r365_tidak_sehat"]\nHORIZON = ["h"]\n\n\ndef origin_table(ispu: pd.DataFrame, holidays: pd.DataFrame, origin: pd.Timestamp, horizon: int = 91,\n                 with_target: bool = True) -> pd.DataFrame:\n    origin = pd.Timestamp(origin)\n    hist = ispu[(ispu.tanggal <= origin) & (ispu.tanggal > origin - pd.Timedelta(days=365))]\n    dates = pd.date_range(origin + pd.Timedelta(days=1), periods=horizon)\n    rows = []\n    for st in STATIONS:\n        h = hist[hist.station == st]\n        h30 = h[h.tanggal > origin - pd.Timedelta(days=30)]\n        if len(h30) < 5:\n            continue\n        state = dict(r30_max=h30["max"].mean(), r30_tidak_sehat=(h30.kelas == 2).mean(), r30_baik=(h30.kelas == 0).mean(),\n                     r365_max=h["max"].mean(), r365_tidak_sehat=(h.kelas == 2).mean())\n        rows.append(pd.DataFrame({"tanggal": dates, "station": st, "stasiun": int(st[-1]), "asal": origin,\n                                  "h": np.arange(1, horizon + 1), **state}))\n    if not rows:\n        return pd.DataFrame()\n    X = pd.concat(rows, ignore_index=True)\n    doy = X.tanggal.dt.dayofyear / 365.25\n    X["doy_sin"], X["doy_cos"] = np.sin(2 * np.pi * doy), np.cos(2 * np.pi * doy)\n    X["hari_minggu"] = X.tanggal.dt.dayofweek\n    X = X.merge(holidays[["tanggal", "is_holiday_nasional"]].rename(columns={"is_holiday_nasional": "libur"}), on="tanggal", how="left")\n    X["libur"] = X.libur.fillna(0)\n    if with_target:\n        X = X.merge(ispu[["tanggal", "station", "kelas"]], on=["tanggal", "station"], how="inner")\n    return X\n\n\ndef training_table(ispu, holidays, origins) -> pd.DataFrame:\n    parts = [origin_table(ispu, holidays, o) for o in origins]\n    return pd.concat([p for p in parts if len(p)], ignore_index=True)\n', 'src/models/__init__.py': '', 'src/models/forecast.py': '"""Backtest rolling-origin, model LightGBM multikelas, dan bobot keputusan untuk macro F1."""\nfrom __future__ import annotations\n\nimport itertools\n\nimport lightgbm as lgb\nimport numpy as np\nimport pandas as pd\nfrom sklearn.metrics import f1_score\n\nWEIGHT_GRID = [0.5, 1, 1.5, 2, 3, 4, 6]\n\n\ndef lgb_model(seed: int = 0):\n    return lgb.LGBMClassifier(n_estimators=300, learning_rate=0.03, num_leaves=15, min_child_samples=50,\n                              subsample=0.8, subsample_freq=1, colsample_bytree=0.8, random_state=seed, verbose=-1)\n\n\ndef macro_f1(y, pred) -> float:\n    return f1_score(y, pred, average="macro")\n\n\ndef decide(P: np.ndarray, w) -> np.ndarray:\n    """Kelas = argmax(peluang × bobot). Bobot SEDANG tetap 1."""\n    return (P * np.asarray(w)).argmax(axis=1)\n\n\ndef tune_weights(P_list, y_list) -> tuple[tuple, float]:\n    """Bobot (BAIK, 1, TIDAK SEHAT) yang memaksimalkan rata-rata macro F1 di beberapa backtest."""\n    best, best_s = (1, 1, 1), -1\n    for wb, wt in itertools.product(WEIGHT_GRID, WEIGHT_GRID):\n        s = np.mean([macro_f1(y, decide(P, (wb, 1, wt))) for P, y in zip(P_list, y_list)])\n        if s > best_s:\n            best, best_s = (wb, 1, wt), s\n    return best, best_s\n\n\ndef train_origins(origins, cutoff: pd.Timestamp, horizon: int = 91):\n    """Tanggal asal yang seluruh 91 hari targetnya sudah lewat sebelum `cutoff`."""\n    return [o for o in origins if o + pd.Timedelta(days=horizon) <= cutoff]\n\n\ndef fit_predict(train: pd.DataFrame, test: pd.DataFrame, features, seeds=range(3)) -> np.ndarray:\n    P = np.zeros((len(test), 3))\n    for s in seeds:\n        m = lgb_model(s).fit(train[features], train.kelas)\n        P[:, m.classes_] += m.predict_proba(test[features])\n    return P / len(list(seeds))\n', 'src/visualization/__init__.py': '', 'src/visualization/plots.py': '"""Gaya grafik yang konsisten dan ramah buta warna (palet Okabe–Ito)."""\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport matplotlib.pyplot as plt\nimport matplotlib.ticker as mtick\nimport seaborn as sns\n\nPALETTE = {"normal": "#0072B2", "fraud": "#D55E00", "accent": "#009E73", "neutral": "#8C8C8C"}\n\n\ndef set_style() -> None:\n    sns.set_theme(style="whitegrid", context="notebook", palette="colorblind")\n    plt.rcParams.update({"figure.dpi": 110, "axes.titleweight": "bold", "axes.titlesize": 12})\n\n\ndef save_fig(fig_dir: Path, name: str) -> None:\n    """Rapikan layout, simpan PNG ke `fig_dir`, lalu tampilkan."""\n    plt.tight_layout()\n    plt.savefig(Path(fig_dir) / f"{name}.png", dpi=130, bbox_inches="tight")\n    plt.show()\n\n\ndef pct_axis(ax, decimals: int = 1, axis: str = "y") -> None:\n    fmt = mtick.PercentFormatter(1, decimals=decimals)\n    (ax.yaxis if axis == "y" else ax.xaxis).set_major_formatter(fmt)\n\n\ndef ref_line(ax, value: float, label: str = "rata-rata") -> None:\n    ax.axhline(value, color=PALETTE["neutral"], ls="--", lw=1.2, label=label)\n'}
NOTEBOOK = json.loads('{\n "cells": [\n  {\n   "cell_type": "markdown",\n   "id": "4688e745",\n   "metadata": {},\n   "source": [\n    "# Meramal Kategori Kualitas Udara Jakarta Tiga Bulan ke Depan\\n",\n    "\\n",\n    "| | |\\n",\n    "| --- | --- |\\n",\n    "| **Kompetisi** | [Air Pollution Prediction, Penyisihan Datavidia 10](https://www.kaggle.com/competitions/penyisihan-datavidia-10) (Arkavidia ITB, Kaggle, Januari–Februari 2026) |\\n",\n    "| **Tujuan** | Meramal kategori ISPU harian di 5 stasiun DKI Jakarta untuk 1 September – 30 November 2025 (metrik macro F1) |\\n",\n    "| **Data** | ISPU harian 2010–Agustus 2025, cuaca harian, NDVI, libur nasional; 455 baris submission |\\n",\n    "| **Penulis** | Fauzan Ahsanudin Alfikri · [Kaggle: fauzan2](https://www.kaggle.com/fauzan2) |\\n",\n    "| **Tanggal** | Disusun ulang November 2026, menggantikan notebook kompetisi Februari 2026 |\\n",\n    "| **Lingkungan** | Dijalankan penuh di Kaggle (CPU) |\\n",\n    "\\n",\n    "**Pertanyaan penelitian.** Dengan data yang berakhir 31 Agustus 2025 (termasuk cuaca), seberapa baik kategori ISPU bisa\\n",\n    "diramal untuk 1–91 hari ke depan, dan informasi apa yang masih berguna sejauh itu?\\n",\n    "\\n",\n    "**Ringkasan temuan.**\\n",\n    "- Data ISPU berakhir 31 Agustus 2025, sama dengan data cuaca, sehingga September–November 2025 harus diramal 1–91 hari ke depan tanpa informasi apa pun dari periode itu.\\n",\n    "- Sejak 2021 PM2.5 menjadi parameter kritis di lebih dari 70% hari, dan proporsi kategori berubah drastis dibanding 2010–2020. Hanya data 2021–2025 yang mewakili periode test.\\n",\n    "- Pada September–November 2021–2024, 79–89% hari berkategori SEDANG, 8–21% TIDAK SEHAT, dan BAIK hampir tidak ada (0–10%). Itulah sebabnya kelas mayoritas sudah memberi macro F1 0,295.\\n",\n    "- Dari 37 backtest bulanan, model terbaik adalah LightGBM dengan fitur kalender dan kondisi stasiun pada tanggal asal, ditambah bobot keputusan untuk macro F1: **0,389 ± 0,083**, naik dari 0,295 (SEDANG untuk semua) dan 0,317 (klimatologi). Keunggulannya menyusut dari 0,43 pada 30 hari pertama menjadi 0,36 pada hari 61–91.\\n",\n    "- Late submission: public **0,292**, private **0,329**. Ini jauh di bawah submission tim terbaik saat kompetisi (private 0,956) dan peringkat 1 (0,977). Selisih sebesar itu tidak bisa dijelaskan oleh peramalan murni dari data sampai Agustus 2025; lihat bagian Kesimpulan.\\n",\n    "\\n",\n    "**Alur:** 1. Setup → 2. Memahami data → 3. EDA → 4. Desain validasi → 5. Baseline → 6. Model →\\n",\n    "7. Bobot keputusan untuk macro F1 → 8. Interpretasi → 9. Submission → 10. Kesimpulan"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "e8d4c830",\n   "metadata": {},\n   "source": [\n    "## 1. Setup\\n",\n    "\\n",\n    "Semua import, parameter, dan path ada di sel ini. Penyeragaman data ISPU ada di `src/data`, tabel peramalan di\\n",\n    "`src/features`, dan backtest serta bobot keputusan di `src/models`."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "80886490",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import os\\n",\n    "import shutil\\n",\n    "import sys\\n",\n    "import time\\n",\n    "import warnings\\n",\n    "from importlib.metadata import version\\n",\n    "from pathlib import Path\\n",\n    "\\n",\n    "import numpy as np\\n",\n    "import pandas as pd\\n",\n    "import matplotlib.pyplot as plt\\n",\n    "import seaborn as sns\\n",\n    "from sklearn.metrics import confusion_matrix, f1_score\\n",\n    "\\n",\n    "SRC_ROOT = Path.cwd().parent\\n",\n    "for r, _, f in os.walk(\\"/kaggle/input\\", followlinks=True):\\n",\n    "    if Path(r).name == \\"models\\" and \\"forecast.py\\" in f:\\n",\n    "        pkg = Path(r).parent\\n",\n    "        if pkg.name == \\"src\\":\\n",\n    "            SRC_ROOT = pkg.parent\\n",\n    "        else:\\n",\n    "            SRC_ROOT = Path(\\"/tmp/project\\")\\n",\n    "            shutil.copytree(pkg, SRC_ROOT / \\"src\\", dirs_exist_ok=True)\\n",\n    "        break\\n",\n    "sys.path.insert(0, str(SRC_ROOT))\\n",\n    "from src.data.load_data import MODEL_CLASSES, STATIONS, find_data_dir, load_holidays, load_ispu, load_weather\\n",\n    "from src.features.build_features import CALENDAR, HORIZON, STATE, origin_table, training_table\\n",\n    "from src.models.forecast import decide, fit_predict, macro_f1, train_origins, tune_weights\\n",\n    "from src.visualization.plots import PALETTE, pct_axis, save_fig, set_style\\n",\n    "\\n",\n    "# ── Parameter eksperimen\\n",\n    "HORIZON_DAYS = 91\\n",\n    "ORIGINS = pd.date_range(\\"2014-12-31\\", \\"2025-08-31\\", freq=\\"ME\\")   # asal bulanan untuk data latih\\n",\n    "FINAL_ORIGIN = pd.Timestamp(\\"2025-08-31\\")\\n",\n    "\\n",\n    "# ── Path\\n",\n    "DATA_DIR = find_data_dir(local=\\"../data/raw\\")\\n",\n    "OUT_DIR = Path(\\"/kaggle/working\\") if Path(\\"/kaggle/working\\").exists() else Path(\\"../reports\\")\\n",\n    "FIG_DIR = OUT_DIR / \\"figures\\"\\n",\n    "FIG_DIR.mkdir(parents=True, exist_ok=True)\\n",\n    "\\n",\n    "warnings.filterwarnings(\\"ignore\\")\\n",\n    "set_style()\\n",\n    "C1, C2, C3, CN = PALETTE[\\"normal\\"], PALETTE[\\"fraud\\"], PALETTE[\\"accent\\"], PALETTE[\\"neutral\\"]\\n",\n    "CLS_COL = {\\"BAIK\\": C3, \\"SEDANG\\": C1, \\"TIDAK SEHAT\\": C2}\\n",\n    "T0 = time.time()\\n",\n    "print(\\"DATA_DIR:\\", DATA_DIR, \\"| OUT_DIR:\\", OUT_DIR)"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "c713679c",\n   "metadata": {},\n   "source": [\n    "## 2. Memahami data\\n",\n    "\\n",\n    "Data ISPU dipublikasikan per tahun dengan format yang berubah-ubah: nama kolom (`pm10` vs `pm_sepuluh`), format tanggal\\n",\n    "(ISO, dd/mm/yyyy, nomor seri Excel), dan penulisan nama stasiun. Semua diseragamkan di `load_ispu`. Baris tanpa kategori\\n",\n    "yang valid (\\"TIDAK ADA DATA\\") dan duplikat dibuang."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "3d8f7eef",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "ispu = load_ispu(DATA_DIR)\\n",\n    "hol = load_holidays(DATA_DIR)\\n",\n    "weather = load_weather(DATA_DIR)\\n",\n    "sample = pd.read_csv(DATA_DIR / \\"sample_submission.csv\\")\\n",\n    "print(f\\"ISPU: {ispu.attrs[\'raw_rows\']:,} baris mentah → {len(ispu):,} baris valid | {ispu.tanggal.min().date()} s.d. {ispu.tanggal.max().date()}\\")\\n",\n    "print(f\\"Cuaca: {weather.tanggal.min().date()} s.d. {weather.tanggal.max().date()} | Submission: {len(sample)} baris, {sample.id.str[:10].min()} s.d. {sample.id.str[:10].max()}\\")\\n",\n    "cov = ispu.groupby([ispu.tanggal.dt.year, \\"station\\"]).size().unstack().fillna(0)\\n",\n    "fig, ax = plt.subplots(figsize=(13, 3.6))\\n",\n    "sns.heatmap(cov.T, cmap=\\"Blues\\", annot=True, fmt=\\".0f\\", cbar=False, ax=ax, annot_kws={\\"fontsize\\": 7})\\n",\n    "ax.set(xlabel=\\"tahun\\", ylabel=\\"\\", title=\\"Jumlah hari berlabel per stasiun dan tahun\\")\\n",\n    "save_fig(FIG_DIR, \\"01_coverage\\")\\n",\n    "ispu.kategori.value_counts().to_frame(\\"hari\\").T"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "763f7a34",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Setelah membersihkan format tanggal yang bercampur (ISO, dd/mm, dan nomor seri Excel), duplikat, dan baris tanpa kategori, tersisa 15.194 hari-stasiun berlabel dari 16.902 baris mentah, 2010 sampai 31 Agustus 2025. Cuaca juga berhenti 31 Agustus 2025, jadi untuk 455 baris submission (5 stasiun × 91 hari) tidak ada fitur yang diamati di periode test. Kategori *sangat tidak sehat* (200 hari) dan *berbahaya* (1 hari) digabung ke TIDAK SEHAT."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "655f4118",\n   "metadata": {},\n   "source": [\n    "## 3. Exploratory Data Analysis\\n",\n    "\\n",\n    "### 3.1 PM2.5 mengubah skala sejak 2021"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "ef1e573e",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "yr = ispu.groupby(ispu.tanggal.dt.year)\\n",\n    "crit = pd.crosstab(ispu.tanggal.dt.year, ispu.critical.where(ispu.critical.isin([\\"PM25\\", \\"PM10\\", \\"O3\\", \\"CO\\", \\"SO2\\", \\"NO2\\"]), \\"lain\\"), normalize=\\"index\\")\\n",\n    "share = pd.crosstab(ispu.tanggal.dt.year, ispu.kategori, normalize=\\"index\\")[[\\"BAIK\\", \\"SEDANG\\", \\"TIDAK SEHAT\\"]]\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(16, 4.3))\\n",\n    "crit[[c for c in [\\"PM25\\", \\"PM10\\", \\"O3\\", \\"CO\\", \\"SO2\\", \\"NO2\\", \\"lain\\"] if c in crit]].plot.bar(stacked=True, ax=ax[0], width=0.85, colormap=\\"tab20\\")\\n",\n    "pct_axis(ax[0], 0); ax[0].set(xlabel=\\"tahun\\", ylabel=\\"porsi hari\\", title=\\"Parameter pencemar kritis\\"); ax[0].legend(fontsize=7, ncol=2)\\n",\n    "share.plot.bar(stacked=True, ax=ax[1], width=0.85, color=[CLS_COL[c] for c in share.columns])\\n",\n    "pct_axis(ax[1], 0); ax[1].set(xlabel=\\"tahun\\", ylabel=\\"porsi hari\\", title=\\"Kategori ISPU per tahun\\"); ax[1].legend(fontsize=8)\\n",\n    "save_fig(FIG_DIR, \\"02_regime\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "5b1df3bb",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Grafik kiri memperlihatkan pergantian alat ukur: sampai 2019 parameter kritis didominasi O3 dan PM10, sedangkan sejak 2021 PM2.5 menjadi parameter kritis di 70–90% hari. Grafik kanan menunjukkan akibatnya: proporsi kategori sebelum 2021 berbeda jauh dan tidak stabil antar tahun. Karena itu backtest dan bobot keputusan hanya dinilai pada periode 2021–2025, walaupun data lama tetap dipakai untuk melatih pola musiman."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "d0b1b1c3",\n   "metadata": {},\n   "source": [\n    "### 3.2 Musim: September–November adalah masa peralihan"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "1e8ef6e6",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "rec = ispu[ispu.tanggal.dt.year >= 2021]\\n",\n    "mon = pd.crosstab(rec.tanggal.dt.month, rec.kategori, normalize=\\"index\\")[[\\"BAIK\\", \\"SEDANG\\", \\"TIDAK SEHAT\\"]]\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(16, 4.3))\\n",\n    "mon.plot.bar(stacked=True, ax=ax[0], width=0.85, color=[CLS_COL[c] for c in mon.columns])\\n",\n    "ax[0].axvspan(7.5, 10.5, color=\\"black\\", alpha=0.08)\\n",\n    "pct_axis(ax[0], 0); ax[0].set(xlabel=\\"bulan\\", ylabel=\\"porsi hari\\", title=\\"Kategori per bulan, 2021–2025 (arsir = periode test)\\"); ax[0].legend(fontsize=8)\\n",\n    "per = rec[rec.tanggal.dt.month.isin([9, 10, 11])]\\n",\n    "yy = pd.crosstab([per.tanggal.dt.year], per.kategori, normalize=\\"index\\").reindex(columns=[\\"BAIK\\", \\"SEDANG\\", \\"TIDAK SEHAT\\"], fill_value=0)\\n",\n    "yy.plot.bar(stacked=True, ax=ax[1], width=0.7, color=[CLS_COL[c] for c in yy.columns])\\n",\n    "pct_axis(ax[1], 0); ax[1].set(xlabel=\\"tahun\\", ylabel=\\"porsi hari\\", title=\\"September–November per tahun\\"); ax[1].legend(fontsize=8)\\n",\n    "save_fig(FIG_DIR, \\"03_season\\")\\n",\n    "yy.style.format(\\"{:.1%}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "ad5307c0",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Musim kering (Mei–Oktober) membawa lebih banyak hari TIDAK SEHAT, sedangkan BAIK muncul terutama Desember–April. Periode test berada di masa peralihan: pada September–November 2021–2024, SEDANG 79–89%, TIDAK SEHAT 8–21%, dan BAIK hanya muncul pada 2021 (10%) dan 2024 (3%). Artinya kelas BAIK di periode test sangat jarang menurut sejarah, padahal macro F1 memberinya bobot sepertiga."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "e89c5323",\n   "metadata": {},\n   "source": [\n    "### 3.3 Cuaca menjelaskan hari buruk, tetapi tidak tersedia untuk periode test\\n",\n    "\\n",\n    "Data cuaca berakhir 31 Agustus 2025, sama dengan ISPU. Jadi cuaca bisa menjelaskan mekanisme, tetapi tidak bisa dipakai\\n",\n    "sebagai fitur untuk September–November."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "042befad",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "wm = rec.merge(weather[[\\"tanggal\\", \\"station\\", \\"precipitation_sum\\", \\"wind_speed_10m_max\\", \\"relative_humidity_2m_mean\\"]], on=[\\"tanggal\\", \\"station\\"], how=\\"inner\\")\\n",\n    "fig, ax = plt.subplots(1, 3, figsize=(17, 4.2))\\n",\n    "for a, (c, lab, bins) in zip(ax, [(\\"precipitation_sum\\", \\"curah hujan (mm)\\", [-0.1, 0, 2, 5, 10, 20, 300]),\\n",\n    "                                  (\\"wind_speed_10m_max\\", \\"angin maksimum (km/jam)\\", [0, 8, 10, 12, 14, 17, 60]),\\n",\n    "                                  (\\"relative_humidity_2m_mean\\", \\"kelembapan rata-rata (%)\\", [0, 70, 75, 80, 85, 100])]):\\n",\n    "    g = wm.groupby(pd.cut(wm[c], bins), observed=True)[\\"max\\"].agg([\\"mean\\", \\"size\\"])\\n",\n    "    ts = wm.groupby(pd.cut(wm[c], bins), observed=True).kelas.apply(lambda s: (s == 2).mean())\\n",\n    "    a.bar([str(i) for i in g.index], ts, color=C2)\\n",\n    "    pct_axis(a, 0); a.set(xlabel=lab, ylabel=\\"porsi hari tidak sehat\\", title=f\\"Hari tidak sehat menurut {lab.split(\' (\')[0]}\\")\\n",\n    "    a.tick_params(axis=\\"x\\", rotation=30)\\n",\n    "save_fig(FIG_DIR, \\"04_weather\\")\\n",\n    "print(wm[[\\"max\\", \\"precipitation_sum\\", \\"wind_speed_10m_max\\", \\"relative_humidity_2m_mean\\"]].corr(method=\\"spearman\\")[\\"max\\"].round(3).to_string())"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "ee8785ab",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Hari tanpa hujan 24% TIDAK SEHAT, sedangkan hari dengan hujan di atas 20 mm hanya 6%. Angin kencang dan udara lembap juga menurunkan porsi hari tidak sehat (korelasi Spearman indeks maksimum dengan hujan −0,31, kelembapan −0,29, angin −0,17). Cuaca menjelaskan mekanisme hari buruk, tetapi karena data cuaca berhenti 31 Agustus, informasi ini tidak bisa dipakai untuk meramal September–November."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "df2d7a05",\n   "metadata": {},\n   "source": [\n    "### 3.4 Berapa lama kondisi hari ini bertahan?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "64cb569d",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "lags = [1, 3, 7, 14, 30, 60, 91]\\n",\n    "ac = {}\\n",\n    "for st in STATIONS:\\n",\n    "    s = rec[rec.station == st].set_index(\\"tanggal\\")[\\"max\\"].asfreq(\\"D\\")\\n",\n    "    an = s - s.groupby(s.index.dayofyear).transform(\\"mean\\")          # anomali terhadap rata-rata hari-dalam-tahun\\n",\n    "    ac[st] = {l: s.autocorr(l) for l in lags} | {f\\"anomali {l}\\": an.autocorr(l) for l in lags}\\n",\n    "ac = pd.DataFrame(ac).mean(axis=1)\\n",\n    "fig, ax = plt.subplots(figsize=(10, 4))\\n",\n    "ax.plot(lags, [ac[l] for l in lags], marker=\\"o\\", color=C1, label=\\"nilai indeks\\")\\n",\n    "ax.plot(lags, [ac[f\\"anomali {l}\\"] for l in lags], marker=\\"s\\", color=C2, label=\\"anomali dari pola musiman\\")\\n",\n    "ax.axhline(0, color=\\"black\\", lw=0.7); ax.set_xscale(\\"log\\"); ax.set_xticks(lags, lags)\\n",\n    "ax.set(xlabel=\\"jarak hari (lag)\\", ylabel=\\"autokorelasi\\", title=\\"Autokorelasi indeks maksimum harian (rata-rata 5 stasiun, 2021–2025)\\"); ax.legend()\\n",\n    "save_fig(FIG_DIR, \\"05_persistence\\")\\n",\n    "print({l: round(ac[f\\"anomali {l}\\"], 2) for l in lags})"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "08302890",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Nilai indeks sangat berkorelasi dengan hari kemarin (0,54 untuk anomali musiman), tetapi korelasi anomali turun cepat ke 0,24 setelah seminggu dan 0,11 setelah sebulan, lalu bertahan di sekitar 0,13–0,15 sampai 91 hari. Kondisi akhir Agustus hanya membantu untuk minggu-minggu awal, dan sisanya harus diisi pola musiman dan tingkat polusi jangka panjang tiap stasiun."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "ec6bb7a8",\n   "metadata": {},\n   "source": [\n    "## 4. Desain validasi\\n",\n    "\\n",\n    "Situasi kompetisi: data berakhir 31 Agustus, lalu 91 hari diramal sekaligus. Backtest meniru situasi itu dari **setiap akhir\\n",\n    "bulan** antara Maret 2021 dan Mei 2025 yang datanya cukup (minimal 250 hari-stasiun berlabel dalam 91 hari berikutnya).\\n",\n    "Satu backtest hanya berisi sekitar 450 baris dan kelas jarang bisa muncul hanya beberapa kali, sehingga skor satu backtest\\n",\n    "sangat bising; rata-rata dari banyak backtest jauh lebih bisa dipercaya. Backtest dengan asal 31 Agustus dilaporkan\\n",\n    "terpisah karena paling mirip dengan periode kompetisi.\\n",\n    "\\n",\n    "Untuk tiap backtest, model hanya dilatih dengan tanggal asal bulanan yang seluruh 91 hari targetnya sudah lewat sebelum\\n",\n    "tanggal asal backtest. Kategori *sangat tidak sehat* dan *berbahaya* (201 hari dalam 15 tahun) digabung ke *tidak sehat*."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "05efcf6d",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "TABLE = training_table(ispu, hol, ORIGINS)\\n",\n    "EVAL = [o for o in pd.date_range(\\"2021-03-31\\", \\"2025-05-31\\", freq=\\"ME\\") if (TABLE.asal == o).sum() >= 250]\\n",\n    "AUG = [o for o in EVAL if o.month == 8]\\n",\n    "BT = {o: TABLE[TABLE.asal == o] for o in EVAL}\\n",\n    "print(f\\"Tabel latih: {len(TABLE):,} baris dari {TABLE.asal.nunique()} tanggal asal | backtest: {len(EVAL)} (asal 31 Agustus: {[o.year for o in AUG]})\\")\\n",\n    "cnt = pd.DataFrame({o.strftime(\\"%Y-%m\\"): BT[o].kelas.value_counts().reindex([0, 1, 2], fill_value=0).values for o in EVAL}, index=MODEL_CLASSES).T\\n",\n    "print(f\\"Backtest tanpa satu pun hari BAIK: {(cnt.BAIK == 0).sum()} | tanpa hari TIDAK SEHAT: {(cnt[\'TIDAK SEHAT\'] == 0).sum()}\\")\\n",\n    "cnt.describe().loc[[\\"mean\\", \\"min\\", \\"max\\"]].round(1)"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "79a4c76f",\n   "metadata": {},\n   "source": [\n    "**Temuan.** 37 backtest memenuhi syarat, termasuk tiga dengan asal 31 Agustus (2021, 2023, 2024). Dua backtest sama sekali tidak memuat hari BAIK, dan jumlah hari BAIK per backtest berkisar 0–196. Variasi sebesar ini menjelaskan kenapa skor satu backtest bisa sangat menyesatkan."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "740a9aac",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "RESULTS, PROBS = {}, {}\\n",\n    "\\n",\n    "def score_preds(name, preds):\\n",\n    "    s = pd.Series({o: macro_f1(BT[o].kelas, preds[o]) for o in EVAL})\\n",\n    "    RESULTS[name] = {\\"rata-rata\\": s.mean(), \\"std\\": s.std(), \\"asal 31 Agustus\\": s[AUG].mean(), \\"per_asal\\": s}\\n",\n    "    return f\\"{name}: rata-rata {s.mean():.3f} ± {s.std():.3f} | asal 31 Agustus {s[AUG].mean():.3f}\\""\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "0d8f885d",\n   "metadata": {},\n   "source": [\n    "## 5. Baseline\\n",\n    "\\n",\n    "- **SEDANG untuk semua hari:** kelas mayoritas.\\n",\n    "- **Klimatologi:** kelas tersering per stasiun dan bulan, dari tahun 2014 sampai tanggal asal.\\n",\n    "- **Kondisi 30 hari terakhir:** kelas tersering per stasiun di 30 hari sebelum tanggal asal, dipakai untuk 91 hari."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "23433d89",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "print(score_preds(\\"SEDANG untuk semua\\", {o: np.ones(len(BT[o]), int) for o in EVAL}))\\n",\n    "clim, last30 = {}, {}\\n",\n    "for o in EVAL:\\n",\n    "    hist = ispu[(ispu.tanggal <= o) & (ispu.tanggal.dt.year >= 2014)]\\n",\n    "    mode = hist.groupby([hist.station, hist.tanggal.dt.month]).kelas.agg(lambda s: s.mode()[0])\\n",\n    "    clim[o] = np.array([mode.get((s, m), 1) for s, m in zip(BT[o].station, BT[o].tanggal.dt.month)])\\n",\n    "    m30 = hist[hist.tanggal > o - pd.Timedelta(days=30)].groupby(\\"station\\").kelas.agg(lambda s: s.mode()[0])\\n",\n    "    last30[o] = BT[o].station.map(m30).fillna(1).astype(int).values\\n",\n    "print(score_preds(\\"klimatologi stasiun × bulan\\", clim))\\n",\n    "print(score_preds(\\"kondisi 30 hari terakhir\\", last30))"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "1c461b53",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Menebak SEDANG untuk semua hari memberi 0,295 (F1 SEDANG tinggi, dua kelas lain nol). Klimatologi per stasiun dan bulan menaikkannya sedikit ke 0,317. Kondisi 30 hari terakhir mencapai 0,373 rata-rata, tetapi dengan simpangan paling besar (±0,137): bagus ketika bulan terakhir mirip tiga bulan berikutnya, buruk ketika musim berganti."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "89e6fe3b",\n   "metadata": {},\n   "source": [\n    "## 6. Model\\n",\n    "\\n",\n    "LightGBM multikelas dengan dua set fitur:\\n",\n    "\\n",\n    "- **Kalender:** stasiun, hari dalam tahun (sin/cos), hari dalam minggu, libur nasional.\\n",\n    "- **Kalender + kondisi di tanggal asal:** ditambah rata-rata indeks dan porsi hari tidak sehat/baik dalam 30 dan 365 hari\\n",\n    "  terakhir, serta jarak ramalan (1–91 hari).\\n",\n    "\\n",\n    "Bagian ini memakai argmax (kelas dengan peluang tertinggi)."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "3cf4f111",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "FEATS = {\\"kalender\\": CALENDAR, \\"kalender + kondisi\\": CALENDAR + STATE + HORIZON}\\n",\n    "t = time.time()\\n",\n    "for name, F in FEATS.items():\\n",\n    "    PROBS[name] = {o: fit_predict(TABLE[TABLE.asal.isin(train_origins(ORIGINS, o, HORIZON_DAYS))], BT[o], F, seeds=range(1)) for o in EVAL}\\n",\n    "    print(score_preds(f\\"LightGBM {name}, argmax\\", {o: PROBS[name][o].argmax(1) for o in EVAL}), f\\"({(time.time() - t) / 60:.1f} menit)\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "1db8a1e1",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Dengan argmax, LightGBM kalender (0,325) hanya sedikit di atas klimatologi karena hampir selalu memilih SEDANG. Menambahkan kondisi stasiun pada tanggal asal menaikkan skor ke 0,363, karena model tahu apakah stasiun sedang berada di periode polusi tinggi atau rendah."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "bb3cc2bc",\n   "metadata": {},\n   "source": [\n    "## 7. Bobot keputusan untuk macro F1\\n",\n    "\\n",\n    "Macro F1 memberi bobot sama untuk setiap kelas, jadi kelas jarang (BAIK, TIDAK SEHAT) perlu lebih sering ditebak daripada\\n",\n    "yang disarankan argmax. Peluang tiap kelas dikalikan bobot, lalu dipilih yang terbesar. Bobot dipilih dengan\\n",\n    "**leave-one-backtest-out**: bobot untuk menilai satu backtest dipilih hanya dari backtest lainnya, sehingga skornya tidak\\n",\n    "bocor."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "1f0fd2d7",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "W_LOO = {}\\n",\n    "for name in FEATS:\\n",\n    "    preds = {}\\n",\n    "    for o in EVAL:\\n",\n    "        others = [z for z in EVAL if z != o]\\n",\n    "        w, _ = tune_weights([PROBS[name][z] for z in others], [BT[z].kelas.values for z in others])\\n",\n    "        W_LOO[(name, o)] = w\\n",\n    "        preds[o] = decide(PROBS[name][o], w)\\n",\n    "    print(score_preds(f\\"LightGBM {name}, bobot macro F1\\", preds))\\n",\n    "res = pd.DataFrame({k: {c: v[c] for c in [\\"rata-rata\\", \\"std\\", \\"asal 31 Agustus\\"]} for k, v in RESULTS.items()}).T.sort_values(\\"rata-rata\\")\\n",\n    "per = pd.DataFrame({k: v[\\"per_asal\\"] for k, v in RESULTS.items()})[res.index]\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(17, 4.8), gridspec_kw={\\"width_ratios\\": [1.2, 1]})\\n",\n    "ax[0].boxplot(per.values, vert=False, showmeans=True, meanprops=dict(marker=\\"D\\", markerfacecolor=\\"black\\", markeredgecolor=\\"black\\", markersize=5))\\n",\n    "for o in AUG:\\n",\n    "    ax[0].scatter(per.loc[o].values, np.arange(1, per.shape[1] + 1), color=C2, s=25, zorder=3)\\n",\n    "ax[0].set_yticks(np.arange(1, per.shape[1] + 1), per.columns)\\n",\n    "ax[0].scatter([], [], color=C2, s=25, label=\\"asal 31 Agustus\\"); ax[0].legend(fontsize=8, loc=\\"lower right\\")\\n",\n    "ax[0].set(xlabel=\\"macro F1 per backtest\\", title=f\\"Skor {len(EVAL)} backtest (berlian = rata-rata)\\")\\n",\n    "best_l = res.index[-1]\\n",\n    "gain = per[best_l] - per[\\"SEDANG untuk semua\\"]\\n",\n    "ax[1].bar(range(len(gain)), gain.values, color=[C2 if o.month == 8 else C1 for o in gain.index])\\n",\n    "ax[1].axhline(0, color=\\"black\\", lw=0.7)\\n",\n    "ax[1].set_xticks(range(0, len(gain), 6), [o.strftime(\\"%Y-%m\\") for o in gain.index[::6]], rotation=30)\\n",\n    "ax[1].set(ylabel=\\"selisih macro F1\\", title=f\\"{best_l}\\\\nvs SEDANG untuk semua, per backtest\\")\\n",\n    "save_fig(FIG_DIR, \\"06_model_comparison\\")\\n",\n    "res.style.format(\\"{:.3f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "e1fa34f2",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Bobot keputusan yang dipilih leave-one-backtest-out menaikkan kedua model: kalender 0,325 → 0,344 dan kalender + kondisi 0,363 → **0,389 ± 0,083**, skor rata-rata terbaik dengan simpangan jauh lebih kecil daripada baseline 30 hari terakhir. Bobot akhir dari semua backtest adalah BAIK 3, SEDANG 1, TIDAK SEHAT 2: model baru menebak kelas jarang ketika peluangnya cukup tinggi dibanding SEDANG."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "61f63e4b",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "FINAL_FEATS = \\"kalender + kondisi\\"\\n",\n    "W_FINAL, w_score = tune_weights([PROBS[FINAL_FEATS][o] for o in EVAL], [BT[o].kelas.values for o in EVAL])\\n",\n    "print(f\\"Model akhir: LightGBM {FINAL_FEATS} | bobot (BAIK, SEDANG, TIDAK SEHAT) dari semua backtest: {W_FINAL} | macro F1 in-sample {w_score:.3f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "c4dd0c2b",\n   "metadata": {},\n   "source": [\n    "## 8. Interpretasi\\n",\n    "\\n",\n    "### 8.1 Ramalan vs kenyataan di backtest 31 Agustus 2024"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "8bda39f1",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "o0 = pd.Timestamp(\\"2024-08-31\\")\\n",\n    "b = BT[o0].copy()\\n",\n    "b[\\"pred\\"] = decide(PROBS[FINAL_FEATS][o0], W_LOO[(FINAL_FEATS, o0)])\\n",\n    "fig, axes = plt.subplots(2, 1, figsize=(16, 5.5), sharex=True)\\n",\n    "for a, col, title in [(axes[0], \\"kelas\\", \\"aktual\\"), (axes[1], \\"pred\\", \\"ramalan\\")]:\\n",\n    "    piv = b.pivot_table(index=\\"station\\", columns=\\"tanggal\\", values=col)\\n",\n    "    a.imshow(piv.values, aspect=\\"auto\\", cmap=plt.matplotlib.colors.ListedColormap([C3, C1, C2]), vmin=0, vmax=2, interpolation=\\"nearest\\")\\n",\n    "    a.set_yticks(range(len(piv)), piv.index); a.set_title(f\\"Asal 31 Agustus 2024: {title} (hijau = baik, biru = sedang, oranye = tidak sehat)\\")\\n",\n    "    ticks = np.arange(0, piv.shape[1], 14)\\n",\n    "    a.set_xticks(ticks, [d.strftime(\\"%d %b\\") for d in piv.columns[ticks]])\\n",\n    "save_fig(FIG_DIR, \\"07_timeline\\")\\n",\n    "print(f\\"Macro F1 backtest ini: {macro_f1(b.kelas, b.pred):.3f}\\")\\n",\n    "pd.DataFrame(confusion_matrix(b.kelas, b.pred, labels=[0, 1, 2]), index=[f\\"aktual {c}\\" for c in MODEL_CLASSES], columns=[f\\"ramal {c}\\" for c in MODEL_CLASSES])"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "4928d076",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Di backtest 31 Agustus 2024 (macro F1 0,472) model menangkap pergantian ke BAIK di akhir November di beberapa stasiun (11 dari 14 hari BAIK tertebak), tetapi hampir tidak menangkap hari TIDAK SEHAT, yang muncul sebagai lonjakan singkat. Lonjakan seperti itu digerakkan cuaca harian, yang tidak tersedia untuk periode ramalan."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "25efdbb4",\n   "metadata": {},\n   "source": [\n    "### 8.2 Fitur apa yang dipakai, dan seberapa cepat ramalan memburuk?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "a9f87fe8",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "from src.models.forecast import lgb_model\\n",\n    "F = FEATS[FINAL_FEATS]\\n",\n    "m = lgb_model(0).fit(TABLE[F], TABLE.kelas)\\n",\n    "imp = pd.Series(m.booster_.feature_importance(\\"gain\\"), index=F)\\n",\n    "imp = (imp / imp.sum()).sort_values()\\n",\n    "rows = []\\n",\n    "for o in EVAL:\\n",\n    "    p = decide(PROBS[FINAL_FEATS][o], W_LOO[(FINAL_FEATS, o)])\\n",\n    "    for lo, hi in [(1, 30), (31, 60), (61, 91)]:\\n",\n    "        mk = BT[o].h.between(lo, hi).values\\n",\n    "        if mk.sum() < 30:\\n",\n    "            continue\\n",\n    "        rows.append({\\"jarak\\": f\\"{lo}–{hi} hari\\", \\"model\\": macro_f1(BT[o].kelas.values[mk], p[mk]),\\n",\n    "                     \\"SEDANG untuk semua\\": macro_f1(BT[o].kelas.values[mk], np.ones(mk.sum()))})\\n",\n    "f1_h = pd.DataFrame(rows).groupby(\\"jarak\\").mean()\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(16, 4.3))\\n",\n    "ax[0].barh(imp.index, imp.values, color=C1); pct_axis(ax[0], 0, axis=\\"x\\"); ax[0].set(xlabel=\\"porsi gain\\", title=\\"Kepentingan fitur\\")\\n",\n    "f1_h.plot.bar(ax=ax[1], color=[C2, CN], rot=0)\\n",\n    "ax[1].set(ylabel=f\\"macro F1 rata-rata {len(EVAL)} backtest\\", title=\\"Macro F1 menurut jarak ramalan\\")\\n",\n    "save_fig(FIG_DIR, \\"08_importance_horizon\\")\\n",\n    "f1_h.round(3)"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "9aa5e8ff",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Fitur terpenting adalah posisi dalam tahun (doy_cos 28%, doy_sin 13%) dan tingkat polusi stasiun dalam 30 dan 365 hari terakhir (r30_max 17%, r365_tidak_sehat 15%, r365_max 11%). Model bekerja sebagai klimatologi yang disesuaikan dengan kondisi terakhir stasiun. Keunggulan atas kelas mayoritas paling besar di 30 hari pertama (0,43 vs 0,34) dan menyusut menjadi 0,36 vs 0,33 di hari 61–91, sesuai dengan autokorelasi yang meluruh di bagian 3.4."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "b0d67142",\n   "metadata": {},\n   "source": [\n    "## 9. Submission\\n",\n    "\\n",\n    "Model dilatih dengan semua tanggal asal yang targetnya lewat sebelum 31 Agustus 2025, lalu meramal dari asal 31 Agustus 2025 dengan bobot akhir."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "4494ed00",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "X_final = origin_table(ispu, hol, FINAL_ORIGIN, HORIZON_DAYS, with_target=False)\\n",\n    "trn = TABLE[TABLE.asal.isin(train_origins(ORIGINS, FINAL_ORIGIN, HORIZON_DAYS))]\\n",\n    "P_final = fit_predict(trn, X_final, FEATS[FINAL_FEATS])\\n",\n    "X_final[\\"category\\"] = np.array(MODEL_CLASSES)[decide(P_final, W_FINAL)]\\n",\n    "X_final[\\"id\\"] = X_final.tanggal.dt.strftime(\\"%Y-%m-%d\\") + \\"_\\" + X_final.station\\n",\n    "sub = sample[[\\"id\\"]].merge(X_final[[\\"id\\", \\"category\\"]], on=\\"id\\", how=\\"left\\")\\n",\n    "assert sub.category.notna().all() and len(sub) == len(sample)\\n",\n    "sub.to_csv(OUT_DIR / \\"submission.csv\\", index=False)\\n",\n    "res.to_csv(OUT_DIR / \\"backtest_results.csv\\")\\n",\n    "fig, ax = plt.subplots(figsize=(16, 2.8))\\n",\n    "piv = X_final.assign(k=decide(P_final, W_FINAL)).pivot_table(index=\\"station\\", columns=\\"tanggal\\", values=\\"k\\")\\n",\n    "ax.imshow(piv.values, aspect=\\"auto\\", cmap=plt.matplotlib.colors.ListedColormap([C3, C1, C2]), vmin=0, vmax=2, interpolation=\\"nearest\\")\\n",\n    "ax.set_yticks(range(len(piv)), piv.index); ticks = np.arange(0, piv.shape[1], 14)\\n",\n    "ax.set_xticks(ticks, [d.strftime(\\"%d %b\\") for d in piv.columns[ticks]]); ax.set_title(\\"Ramalan September–November 2025\\")\\n",\n    "save_fig(FIG_DIR, \\"09_forecast\\")\\n",\n    "sub.category.value_counts(normalize=True).to_frame(\\"porsi\\").style.format(\\"{:.1%}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "1ecf3bee",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Ramalan akhir 93,8% SEDANG dan 6,2% BAIK, dengan BAIK muncul di akhir November di DKI1, DKI4, dan DKI5, sesuai pola musim peralihan. Tidak ada hari TIDAK SEHAT yang ditebak, karena dari data sampai Agustus tidak ada sinyal yang cukup kuat untuk menunjuk hari tertentu."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "a31b42c7",\n   "metadata": {},\n   "source": [\n    "## 10. Kesimpulan\\n",\n    "\\n",\n    "1. **Ramalan 91 hari ke depan hanya sedikit lebih baik daripada kelas mayoritas.** Model terbaik mencapai macro F1 0,389 di 37 backtest, dibanding 0,295 untuk SEDANG semua dan 0,317 untuk klimatologi.\\n",\n    "2. **Informasi yang berguna adalah musim dan kondisi stasiun terakhir.** Cuaca menjelaskan hari buruk tetapi berhenti di 31 Agustus; autokorelasi anomali turun ke sekitar 0,1 setelah sebulan.\\n",\n    "3. **Bobot keputusan penting untuk macro F1.** Mengalikan peluang dengan bobot kelas (3, 1, 2) menaikkan skor 0,02–0,03 tanpa mengubah model.\\n",\n    "4. **Hasil.** Late submission public 0,292 dan private 0,329, setara dengan skor backtest. Submission tim terbaik saat kompetisi mencapai private 0,956 dan peringkat 1 mencapai 0,977. Skor setinggi itu jauh di atas apa yang dicapai peramalan dari data sampai Agustus 2025 di backtest (rata-rata 0,39 ± 0,08), sehingga kemungkinan besar memanfaatkan informasi tentang kondisi aktual September–November 2025 (misalnya data ISPU yang dipublikasikan kemudian). Notebook ini sengaja hanya memakai data yang diberikan dan tidak mencoba mereproduksi pendekatan itu.\\n",\n    "\\n",\n    "**Keterbatasan.** Satu periode test hanya berisi 455 baris, sehingga skor leaderboard sangat bergantung pada beberapa hari kelas jarang. Backtest 2021–2025 juga hanya mencakup empat musim September–November.\\n",\n    "\\n",\n    "### Jejak lingkungan"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "099af2f8",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import platform\\n",\n    "pkgs = [\\"numpy\\", \\"pandas\\", \\"scikit-learn\\", \\"lightgbm\\", \\"matplotlib\\", \\"seaborn\\"]\\n",\n    "print(\\" | \\".join([f\\"python {platform.python_version()}\\"] + [f\\"{p} {version(p)}\\" for p in pkgs]))\\n",\n    "print(f\\"Waktu eksekusi total: {(time.time() - T0) / 60:.1f} menit\\")"\n   ]\n  }\n ],\n "metadata": {\n  "kernelspec": {\n   "display_name": "Python 3",\n   "language": "python",\n   "name": "python3"\n  },\n  "language_info": {\n   "name": "python",\n   "version": "3.11"\n  }\n },\n "nbformat": 4,\n "nbformat_minor": 5\n}')

